class MyIterator:
    def __init__(self, limit):
        self.num = 0
        self.limit = limit
    def __iter__(self):
        return self
    def __next__(self):
        if self.num < self.limit:
            val = self.num
            self.num += 1
            return val
        else:
            raise StopIteration

it = MyIterator(3)
for i in it:
    print(i)

creating_custom_iterators.example_code:
class ReverseList:
    def __init__(self, data):
        self.data = data
        self.index = len(data)
    def __iter__(self):
        return self
    def __next__(self):
        if self.index == 0:
            raise StopIteration
        self.index -= 1
        return self.data[self.index]

rev = ReverseList([1,2,3])
for i in rev:
    print(i)

