import time

def timer(func):
    def wrapper(*args, **kwargs):
        start = time.time()
        result = func(*args, **kwargs)
        end = time.time()
        print(f'Time taken: {end-start}')
        return result
    return wrapper

@timer
def compute():
    total = 0
    for i in range(1000000):
        total += i
    return total

compute()

